CREATE TEMPORARY VIEW srp_user_keyword_cat_level_grouped_${grass_region_without_quote} AS
SELECT
    a.user_id AS user_id
    ,COALESCE(abs_tier_180d, '0') AS abs_tier_180d
    ,COALESCE(level1_keyword_category_max_imp, 'NULL') AS level1_keyword_category_max_imp
    ,COALESCE(platform_gmv_180d_pct_category, 'NULL') AS platform_gmv_180d_pct_category
    ,COALESCE(search_gmv_180d_pct_category, 'NULL') AS search_gmv_180d_pct_category
    ,COALESCE(platform_duration_180d_pct_category, 'NULL') AS platform_duration_180d_pct_category
    ,COALESCE(search_duration_180d_pct_category, 'NULL') AS search_duration_180d_pct_category
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(view_cnt) AS view_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
FROM
    srdi_mart.dws_sr_data_warehouse_search_srp_user_benchmark_1d a
LEFT JOIN
    keyword_wide_${grass_region_without_quote} b
ON
    a.keyword = b.keyword
LEFT JOIN
    user_label_${grass_region_without_quote} c
ON
    a.user_id = c.user_id
WHERE
    local_date = ${local_date}
    AND grass_region IN (${grass_region})
    AND a.user_id > 0
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND (view_cnt > 0 OR (page_section IS NULL AND target_type IN ('item','video','livestream')))
GROUP BY
    1,2,3,4,5,6,7;

