CREATE TEMPORARY VIEW srp_user_grouped_${grass_region_without_quote} AS
SELECT
    user_id
    ,abs_tier_180d
    ,platform_gmv_180d_pct_category
    ,search_gmv_180d_pct_category
    ,platform_duration_180d_pct_category
    ,search_duration_180d_pct_category
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(view_cnt) AS view_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,CASE WHEN SUM(order_cnt) > 0 THEN SUM(gmv) / SUM(order_cnt) ELSE 0 END AS abs
FROM
    srp_user_keyword_cat_level_grouped_${grass_region_without_quote}
GROUP BY
    1,2,3,4,5,6;

