CREATE TEMPORARY VIEW dws_search_metrics_${grass_region_without_quote} AS
SELECT
/*+ BROADCASTJOIN(c) */
    exp_group_id
    ,experiment_id
    ,IF(GROUPING(abs_tier_180d) = 1, '__ALL__', abs_tier_180d) AS abs_tier_180d
    ,'__ALL__' AS level1_keyword_category_max_imp
    ,IF(GROUPING(platform_gmv_180d_pct_category) = 1, '__ALL__', platform_gmv_180d_pct_category) AS platform_gmv_180d_pct_category
    ,IF(GROUPING(search_gmv_180d_pct_category) = 1, '__ALL__', search_gmv_180d_pct_category) AS search_gmv_180d_pct_category
    ,IF(GROUPING(platform_duration_180d_pct_category) = 1, '__ALL__', platform_duration_180d_pct_category) AS platform_duration_180d_pct_category
    ,IF(GROUPING(search_duration_180d_pct_category) = 1, '__ALL__', search_duration_180d_pct_category) AS search_duration_180d_pct_category
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(IF(imp_cnt > 0, 1, NULL)) AS imp_uu
    ,SUM(click_cnt) AS click_cnt
    ,SUM(IF(click_cnt > 0, 1, NULL)) AS click_uu
    ,SUM(order_cnt) AS order_cnt
    ,SUM(IF(order_cnt > 0, 1, NULL)) AS order_uu
    ,SUM(IF(view_cnt > 0, 1, NULL)) AS search_uu
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,SUM(IF(abs <= global_search_abs_995, gmv, 0)) as gmv_995
    ,SUM(IF(abs <= global_search_abs_995, gmv, 0)) / SUM(IF(imp_cnt > 0 AND abs <= global_search_abs_995, 1, NULL)) AS gmv_uu_995
    ,SUM(IF(abs <= global_search_abs_995, pc2_gmv, 0)) AS pc2_gmv_995
    ,SUM(IF(abs <= global_search_abs_995, pc2_gmv, 0)) / SUM(IF(imp_cnt > 0 AND abs <= global_search_abs_995, 1, NULL)) AS pc2_gmv_uu_995
FROM
    srp_user_grouped_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
JOIN
    global_search_abs995_benchmark_${grass_region_without_quote} c
GROUP BY GROUPING SETS (
    (exp_group_id, experiment_id)
    ,(exp_group_id, experiment_id, abs_tier_180d)
    ,(exp_group_id, experiment_id, platform_gmv_180d_pct_category)
    ,(exp_group_id, experiment_id, search_gmv_180d_pct_category)
    ,(exp_group_id, experiment_id, platform_duration_180d_pct_category)
    ,(exp_group_id, experiment_id, search_duration_180d_pct_category)
)
UNION ALL
SELECT
    exp_group_id
    ,experiment_id
    ,IF(GROUPING(abs_tier_180d) = 1, '__ALL__', abs_tier_180d) AS abs_tier_180d
    ,level1_keyword_category_max_imp
    ,'__ALL__' AS platform_gmv_180d_pct_category
    ,'__ALL__' AS search_gmv_180d_pct_category
    ,'__ALL__' AS platform_duration_180d_pct_category
    ,'__ALL__' AS search_duration_180d_pct_category
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(IF(imp_cnt > 0, 1, NULL)) AS imp_uu
    ,SUM(click_cnt) AS click_cnt
    ,SUM(IF(click_cnt > 0, 1, NULL)) AS click_uu
    ,SUM(order_cnt) AS order_cnt
    ,SUM(IF(order_cnt > 0, 1, NULL)) AS order_uu
    ,SUM(IF(view_cnt > 0, 1, NULL)) AS search_uu
    ,SUM(gmv) AS gmv
    ,NULL AS pc2_gmv
    ,NULL AS gmv_995
    ,NULL AS gmv_uu_995
    ,NULL AS pc2_gmv_995
    ,NULL AS pc2_gmv_uu_995
FROM
    srp_user_keyword_cat_level_grouped_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY
    exp_group_id, experiment_id, CUBE(abs_tier_180d), level1_keyword_category_max_imp;

