CREATE TEMPORARY VIEW edt_metric_user_level_${grass_region_without_quote} AS
SELECT
    a.user_id AS user_id
    ,COALESCE(abs_tier_180d, '0') AS abs_tier_180d
    ,COALESCE(platform_gmv_180d_pct_category, 'NULL') AS platform_gmv_180d_pct_category
    ,COALESCE(search_gmv_180d_pct_category, 'NULL') AS search_gmv_180d_pct_category
    ,COALESCE(platform_duration_180d_pct_category, 'NULL') AS platform_duration_180d_pct_category
    ,COALESCE(search_duration_180d_pct_category, 'NULL') AS search_duration_180d_pct_category
    ,SUM(edtmax_in_days) AS edt_numerator
    ,SUM(IF(edtmax_in_days IS NOT NULL, 1, 0)) AS edt_denominator
FROM
    srdi_mart.dwd_fp_search_base_1d a
LEFT JOIN
    dwd_edt_order_info_${grass_region_without_quote} b
ON
    a.order_id = b.order_id
LEFT JOIN
    user_label_${grass_region_without_quote} c
ON
    a.user_id = c.user_id
WHERE
    dt = ${local_date}
    AND country = ${grass_region}
    AND a.user_id > 0
    AND a.order_id IS NOT NULL
GROUP BY
    1,2,3,4,5,6;

