CREATE TEMPORARY VIEW dws_edt_metrics_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,IF(GROUPING(abs_tier_180d) = 1, '__ALL__', abs_tier_180d) AS abs_tier_180d
    ,IF(GROUPING(platform_gmv_180d_pct_category) = 1, '__ALL__', platform_gmv_180d_pct_category) AS platform_gmv_180d_pct_category
    ,IF(GROUPING(search_gmv_180d_pct_category) = 1, '__ALL__', search_gmv_180d_pct_category) AS search_gmv_180d_pct_category
    ,IF(GROUPING(platform_duration_180d_pct_category) = 1, '__ALL__', platform_duration_180d_pct_category) AS platform_duration_180d_pct_category
    ,IF(GROUPING(search_duration_180d_pct_category) = 1, '__ALL__', search_duration_180d_pct_category) AS search_duration_180d_pct_category
    ,SUM(edt_numerator) / SUM(edt_denominator) AS avg_edt
FROM
    edt_metric_user_level_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON 
    a.user_id = b.user_id
GROUP BY GROUPING SETS (
    (exp_group_id)
    ,(exp_group_id, abs_tier_180d)
    ,(exp_group_id, experiment_id, platform_gmv_180d_pct_category)
    ,(exp_group_id, experiment_id, search_gmv_180d_pct_category)
    ,(exp_group_id, experiment_id, platform_duration_180d_pct_category)
    ,(exp_group_id, experiment_id, search_duration_180d_pct_category)
);
    
