CREATE TEMPORARY VIEW ads_user_grouped_${grass_region_without_quote} AS
SELECT
    user_id
    ,abs_tier_180d
    ,platform_gmv_180d_pct_category
    ,search_gmv_180d_pct_category
    ,platform_duration_180d_pct_category
    ,search_duration_180d_pct_category
    ,SUM(ads_load_numerator) AS ads_load_numerator
    ,SUM(ads_rev) AS ads_rev
    ,SUM(ads_broad_roi_numerator_local) AS ads_broad_roi_numerator_local
    ,SUM(ads_narrow_roi_numerator) AS ads_narrow_roi_numerator
FROM
    ads_user_keyword_cat_grouped_${grass_region_without_quote}
GROUP BY
    1,2,3,4,5,6;

--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_user_full_join_${grass_region_without_quote} AS
SELECT
/*+ BROADCASTJOIN(c) */
    COALESCE(a.user_id, b.user_id) AS user_id
    ,COALESCE(a.abs_tier_180d, b.abs_tier_180d) AS abs_tier_180d
    ,COALESCE(a.platform_gmv_180d_pct_category, b.platform_gmv_180d_pct_category) AS platform_gmv_180d_pct_category
    ,COALESCE(a.search_gmv_180d_pct_category, b.search_gmv_180d_pct_category) AS search_gmv_180d_pct_category
    ,COALESCE(a.platform_duration_180d_pct_category, b.platform_duration_180d_pct_category) AS platform_duration_180d_pct_category
    ,COALESCE(a.search_duration_180d_pct_category, b.search_duration_180d_pct_category) AS search_duration_180d_pct_category
    ,ads_load_numerator
    ,ads_load_denominator
    ,ads_rev
    ,ads_broad_roi_numerator_local / exchange_rate AS ads_broad_roi_numerator
    ,ads_narrow_roi_numerator
FROM
    dwd_ads_load_denominator_${grass_region_without_quote} a
FULL JOIN
    ads_user_grouped_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
JOIN
    exchange_rate_${grass_region_without_quote} c;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_ads_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,IF(GROUPING(abs_tier_180d) = 1, '__ALL__', abs_tier_180d) AS abs_tier_180d
    ,'__ALL__' AS level1_keyword_category_max_imp
    ,IF(GROUPING(platform_gmv_180d_pct_category) = 1, '__ALL__', platform_gmv_180d_pct_category) AS platform_gmv_180d_pct_category
    ,IF(GROUPING(search_gmv_180d_pct_category) = 1, '__ALL__', search_gmv_180d_pct_category) AS search_gmv_180d_pct_category
    ,IF(GROUPING(platform_duration_180d_pct_category) = 1, '__ALL__', platform_duration_180d_pct_category) AS platform_duration_180d_pct_category
    ,IF(GROUPING(search_duration_180d_pct_category) = 1, '__ALL__', search_duration_180d_pct_category) AS search_duration_180d_pct_category
    ,SUM(ads_rev) AS ads_rev
    ,SUM(ads_load_numerator) / SUM(ads_load_denominator) AS ads_load
    ,SUM(ads_narrow_roi_numerator) / SUM(ads_rev) AS ads_narrow_roi
    ,SUM(ads_broad_roi_numerator) / SUM(ads_rev) AS ads_broad_roi
FROM
    ads_user_full_join_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY GROUPING SETS (
    (exp_group_id)
    ,(exp_group_id, abs_tier_180d)
    ,(exp_group_id, platform_gmv_180d_pct_category)
    ,(exp_group_id, search_gmv_180d_pct_category)
    ,(exp_group_id, platform_duration_180d_pct_category)
    ,(exp_group_id, search_duration_180d_pct_category)
)
UNION ALL
SELECT
    exp_group_id
    ,IF(GROUPING(abs_tier_180d) = 1, '__ALL__', abs_tier_180d) AS abs_tier_180d
    ,level1_keyword_category_max_imp
    ,'__ALL__' AS platform_gmv_180d_pct_category
    ,'__ALL__' AS search_gmv_180d_pct_category
    ,'__ALL__' AS platform_duration_180d_pct_category
    ,'__ALL__' AS search_duration_180d_pct_category
    ,SUM(ads_rev) AS ads_rev
    ,NULL AS ads_load
    ,NULL AS ads_narrow_roi
    ,NULL AS ads_broad_roi
FROM
    ads_user_keyword_cat_grouped_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY
    exp_group_id, CUBE(abs_tier_180d), level1_keyword_category_max_imp;

--sql_divide_splitter--

